spec.css:
/* Blocks: every edge square, every surface bevelled like a cube face, the
   backdrop a wall of dirt under a strip of grass, drawn in gradients so the
   theme carries no file. */
.bg-backdrop {
  background-color: var(--color-backdrop-to);
  background-image:
    linear-gradient(to bottom, var(--color-backdrop-from) 0, var(--color-backdrop-from) 48px, transparent 48px),
    repeating-linear-gradient(0deg, rgb(0 0 0 / 0.16) 0 2px, transparent 2px 32px),
    repeating-linear-gradient(90deg, rgb(0 0 0 / 0.16) 0 2px, transparent 2px 32px),
    repeating-linear-gradient(45deg, rgb(255 255 255 / 0.04) 0 8px, transparent 8px 16px);
  background-size: 100% 100%, 32px 32px, 32px 32px, 48px 48px;
  background-attachment: fixed;
  image-rendering: pixelated;
}
[data-rail], [data-sidebar] {
  --color-surface: #6a6a6a;
  --color-surface-raised: #7d7d7d;
  --color-border: #3a3a3a;
  --color-border-strong: #1f1f1f;
  --color-ink: #f4f4f4;
  --color-ink-muted: #d0d0d0;
  --color-ink-subtle: #a8a8a8;
  --color-accent: #7fc9ff;
  --color-accent-subtle: #4b5a6b;
  --color-selection: #4b5a6b;
  background-image:
    repeating-linear-gradient(0deg, rgb(0 0 0 / 0.18) 0 2px, transparent 2px 24px),
    repeating-linear-gradient(90deg, rgb(0 0 0 / 0.18) 0 2px, transparent 2px 24px);
}
button, [role="button"], input, select, textarea {
  box-shadow: inset -3px -3px 0 rgb(0 0 0 / 0.35), inset 3px 3px 0 rgb(255 255 255 / 0.35);
}
button:active, [role="button"]:active {
  box-shadow: inset 3px 3px 0 rgb(0 0 0 / 0.35), inset -3px -3px 0 rgb(255 255 255 / 0.2);
}
[data-shell-header] {
  border-bottom-width: 4px;
}
